/* Nick Reyna CRM: selector de equipos y PDF autocontenido. Sin servicios externos. */
(()=>{
  const $=id=>document.getElementById(id);
  const equipos=[
    ['DJ profesional',1],['Parlantes JBL EON 615',2],['Micrófonos',2],
    ['PAR LED',4],['Efecto Derby',1],['Máquina de burbujas',1],['Láser',1]
  ];
  const limites=Object.fromEntries(equipos);
  const grid=$('n-equipo-grid');
  // Time choices in half-hour steps: avoids typing on mobile and desktop.
  const horaSelect=$('n-hora');
  for(let h=0;h<24;h++) for(const m of [0,30]){
    const time=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');
    const opt=document.createElement('option'); opt.value=time;
    const hh=h%12||12; opt.textContent=hh+':'+String(m).padStart(2,'0')+' '+(h<12?'a. m.':'p. m.');
    horaSelect.appendChild(opt);
  }
  // Native calendar (Safari/Chrome/Brave); fall back to focusing the date input.
  $('n-fecha-abrir').addEventListener('click',()=>{
    const input=$('n-fecha');
    try { if(typeof input.showPicker==='function') input.showPicker(); else {input.focus();input.click();} }
    catch(e) { input.focus(); input.click(); }
  });

  const iconos={'DJ profesional':'🎧','Parlantes JBL EON 615':'🔊','Micrófonos':'🎤','PAR LED':'💡','Efecto Derby':'🌈','Máquina de burbujas':'🫧','Láser':'✨'};
  for(const [nombre,max] of equipos){
    const fila=document.createElement('div');fila.className='equipo-fila';
    const titulo=document.createElement('span');titulo.className='equipo-titulo';titulo.textContent=(iconos[nombre]||'✓')+' '+nombre;
    const subtitulo=document.createElement('small');subtitulo.textContent='MÁX. '+max+' · Selecciona la cantidad';
    const ctrl=document.createElement('div');ctrl.className='equipo-control';
    const menos=document.createElement('button');menos.type='button';menos.textContent='−';menos.setAttribute('aria-label','Reducir '+nombre);
    const sel=document.createElement('select');sel.dataset.equipo=nombre;sel.setAttribute('aria-label','Cantidad de '+nombre);
    for(let n=0;n<=max;n++){const opt=document.createElement('option');opt.value=String(n);opt.textContent=String(n);sel.appendChild(opt);}
    const mas=document.createElement('button');mas.type='button';mas.textContent='+';mas.setAttribute('aria-label','Aumentar '+nombre);
    menos.addEventListener('click',()=>{sel.value=Math.max(0,Number(sel.value)-1);sel.dispatchEvent(new Event('change',{bubbles:true}));});
    mas.addEventListener('click',()=>{sel.value=Math.min(max,Number(sel.value)+1);sel.dispatchEvent(new Event('change',{bubbles:true}));});
    ctrl.append(menos,sel,mas);fila.append(titulo,subtitulo,ctrl);grid.appendChild(fila);
  }
  function resumen(){
    const plan=$('n-plan').value;const total=Number($('n-total').value)||0;
    $('n-resumen-plan').textContent=plan?('Plan: '+plan):'Selecciona tu plan';
    const items=Array.from(grid.querySelectorAll('select')).filter(s=>Number(s.value)>0).map(s=>s.value+' × '+s.dataset.equipo);
    $('n-resumen-equipo').textContent=plan==='Personalizado'?(items.join(' · ')||'Selecciona el equipo que necesites'):'Servicios incluidos según el paquete';
    $('n-resumen-total').textContent='S/'+total.toFixed(2);
    $('n-resumen-adelanto').textContent='S/'+(total/2).toFixed(2);
  }
  grid.addEventListener('change',resumen);$('n-total').addEventListener('input',resumen);
  $('n-plan').addEventListener('change',resumen);
  function refresh(){ $('n-equipo-box').hidden=$('n-plan').value!=='Personalizado'; resumen(); }
  $('n-plan').addEventListener('change',refresh);
  window.resetearCotizadorExtra=()=>{
    grid.querySelectorAll('select').forEach(s=>s.value='0');
    $('n-horas').value='5';$('n-hora').value='';$('n-descripcion').value='';refresh();
  };
  window.obtenerDetallesCotizacion=()=>{
    const items=Array.from(grid.querySelectorAll('select')).filter(s=>Number(s.value)>0).map(s=>`${s.value} ${s.dataset.equipo}`);
    return {equipoTexto:$('n-plan').value==='Personalizado'?items.join(', '):'',
       descripcion:$('n-descripcion').value.trim(),duracion:$('n-horas').value,
       hora:$('n-hora').value};
  };
  let ultima=null;
  window.guardarUltimaCotizacion=obj=>{ultima=obj;};

  // Generador PDF compacto, sin CDN: texto WinAnsi y logotipo JPEG incrustado.
  const cp1252={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};
  function bin(s){const a=new Uint8Array(s.length);for(let i=0;i<s.length;i++){const c=s[i],k=s.charCodeAt(i);a[i]= k<=255?k:(cp1252[c]||63);}return a;}
  function pdfEsc(s){return String(s).replace(/[^\x20-\x7E\xA0-\xFF€‚ƒ„…†‡ˆ‰Š‹ŒŽ‘’“”•–—˜™š›œžŸ]/g,'?').replace(/[\\()]/g,'\\$&');}
  function wrap(s,max=76){const words=String(s).split(/\s+/);const out=[];let row='';for(const word of words){if((row+' '+word).trim().length>max){if(row)out.push(row);row=word;}else row=(row+' '+word).trim();}if(row)out.push(row);return out;}
  const jpegBase64='';
  function pdfData(c){
    const total=Number(c.total)||0;
    const fecha=c.fecha_evento?new Date(c.fecha_evento+'T12:00:00').toLocaleDateString('es-PE'):'Por confirmar';
    const hoy=new Date().toLocaleDateString('es-PE');
    const tipo=String(c.tipo_evento||'Evento');
    const detalle=(c.plan==='Personalizado')
      ? (c.equipoTexto?c.equipoTexto.split(', ').map(x=>x.trim()).filter(Boolean):['Equipos por confirmar'])
      : ({'Básico':['DJ profesional · 3 horas','1 micrófono','Todos los géneros musicales','Movilidad según cobertura'],
          'Estándar':['DJ profesional · 5 horas','1 parlante JBL EON 615','1 micrófono','Todos los géneros musicales','Movilidad según cobertura'],
          'Plus':['DJ profesional · 5 horas','2 parlantes JBL EON 615','2 micrófonos','4 PAR LED + 1 efecto Derby','Todos los géneros musicales','Movilidad según cobertura']}[c.plan]||['Servicio de DJ profesional']);
    const pages=[];
    let commands='';let y=0;
    const rgb=(r,g,b)=>`${r} ${g} ${b}`;
    const rect=(x,b,w,h,r,g,bl)=>{commands+=`${rgb(r,g,bl)} rg ${x} ${b} ${w} ${h} re f\n`;};
    const text=(str,x,base,size=11,bold=false,r=0.12,g=0.12,b=.14)=>{
      commands+=`${rgb(r,g,b)} rg BT /${bold?'F2':'F1'} ${size} Tf 1 0 0 1 ${x} ${base} Tm (${pdfEsc(str)}) Tj ET\n`;
    };
    const rule=(yy)=>rect(50,yy,495,1,.88,.88,.89);
    const startPage=(continuation=false)=>{
      commands=''; rect(0,0,595,842,1,1,1);
      rect(0,724,595,118,.065,.065,.075);
      rect(0,718,595,6,.98,.075,.22);
      text('NICK REYNA DJ',48,789,24,true,1,1,1);
      text('DJ  ·  EVENTOS  ·  EXPERIENCIAS',49,771,9,false,.82,.82,.83);
      text(continuation?'COTIZACIÓN · CONTINUACIÓN':'COTIZACIÓN DE SERVICIO',49,742,13,true,1,1,1);
      commands+='q 77 0 0 77 474 737 cm /Logo Do Q\n';
      text('N.º '+String(c.codigo||'—'),50,691,10,true,.68,.07,.17);
      text('Emitida: '+hoy,390,691,10,false,.35,.35,.38);
      rule(678);
      y=654;
    };
    const finishPage=()=>{
      rule(53);
      text('NICK REYNA DJ  |  www.nickreyna.com  |  Emitimos boletas y facturas',50,37,9,false,.42,.42,.45);
      pages.push(commands);
    };
    const checkSpace=(needed=52)=>{if(y-needed<83){finishPage();startPage(true);}};
    const section=(label)=>{checkSpace(50);text(label,50,y,11,true,.68,.07,.17);y-=12;rule(y);y-=20;};
    const line=(label,value)=>{checkSpace(21);text(label,55,y,10,false,.45,.45,.48);text(String(value||'—'),197,y,10,true,.10,.10,.12);y-=21;};
    startPage();
    section('DATOS DEL EVENTO');
    line('Cliente',c.cliente||'Por confirmar');
    line('Evento',tipo);
    line('Fecha y hora',fecha+(c.hora?'  ·  '+c.hora:''));
    for(const [i,x] of wrap(c.lugar||'Por confirmar',51).entries())line(i?'':'Lugar',x);
    line('Plan',c.plan||'Por confirmar');
    line('Duración',(c.duracion||'Por confirmar')+' horas');
    y-=7;
    section('SERVICIOS INCLUIDOS');
    for(const item of detalle){
      for(const textLine of wrap(item,77)){
        checkSpace(19);rect(57,y-1,5,5,.98,.075,.22);text(textLine,71,y-3,10,false,.17,.17,.19);y-=20;
      }
    }
    if(c.descripcion){
      y-=6;section('OBSERVACIONES');
      for(const item of wrap(c.descripcion,84)){checkSpace(17);text(item,55,y,10,false,.24,.24,.27);y-=17;}
    }
    checkSpace(133); y-=13;
    rect(49,y-111,497,111,.075,.075,.085);
    rect(49,y-111,5,111,.98,.075,.22);
    text('TOTAL DEL SERVICIO',67,y-30,12,true,1,1,1);
    text('S/ '+total.toFixed(2),355,y-33,23,true,1,1,1);
    text('Adelanto para reservar (50%)',67,y-65,10,false,.82,.82,.83);
    text('S/ '+(total/2).toFixed(2),435,y-65,11,true,1,1,1);
    text('Saldo restante',67,y-87,10,false,.82,.82,.83);
    text('S/ '+(total/2).toFixed(2),435,y-87,11,true,1,1,1);
    y-=130;
    for(const statement of ['Fecha sujeta a disponibilidad. Reserva confirmada con el adelanto.',
       'Precios y movilidad según lo acordado para el evento.']){
      checkSpace(16);text(statement,52,y,9,false,.43,.43,.46);y-=16;
    }
    finishPage();
    const chunks=[];let length=0;const offsets=[0];
    const append=u=>{chunks.push(u);length+=u.length;};
    const str=v=>append(bin(v));
    str('%PDF-1.4\n%âãÏÓ\n');
    function obj(id,content){offsets[id]=length;str(`${id} 0 obj\n${content}\nendobj\n`);}
    const count=pages.length,imgId=5+2*count;
    obj(1,'<< /Type /Catalog /Pages 2 0 R >>');
    obj(2,`<< /Type /Pages /Count ${count} /Kids [ ${pages.map((_,i)=>`${5+2*i} 0 R`).join(' ')} ] >>`);
    obj(3,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
    obj(4,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
    pages.forEach((cmd,i)=>{
      const pid=5+2*i,cid=6+2*i;
      obj(pid,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Logo ${imgId} 0 R >> >> /Contents ${cid} 0 R >>`);
      const bytes=bin(cmd);
      offsets[cid]=length;str(`${cid} 0 obj\n<< /Length ${bytes.length} >>\nstream\n`);append(bytes);str('\nendstream\nendobj\n');
    });
    const jpeg=Uint8Array.from(atob(jpegBase64),x=>x.charCodeAt(0));
    offsets[imgId]=length;str(`${imgId} 0 obj\n<< /Type /XObject /Subtype /Image /Width 512 /Height 512 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`);append(jpeg);str('\nendstream\nendobj\n');
    const xref=length;str(`xref\n0 ${imgId+1}\n0000000000 65535 f \n`);
    for(let id=1;id<=imgId;id++)str(`${String(offsets[id]).padStart(10,'0')} 00000 n \n`);
    str(`trailer\n<< /Size ${imgId+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);
    return new Blob(chunks,{type:'application/pdf'});
  }
  function archivo(){if(!ultima)throw Error('Primero guarda la cotización.');const nombre='Cotizacion-'+String(ultima.codigo).replace(/[^a-zA-Z0-9-]/g,'')+'.pdf';return new File([pdfData(ultima)],nombre,{type:'application/pdf'});}
  $('nueva-pdf-descargar').addEventListener('click',()=>{try{const f=archivo(),url=URL.createObjectURL(f),a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('nueva-pdf-msg').textContent='PDF descargado.';}catch(e){$('nueva-pdf-msg').textContent=e.message;}});
  $('nueva-pdf-compartir').addEventListener('click',async()=>{
    try{
      const f=archivo();
      if(!navigator.canShare||!navigator.canShare({files:[f]})||!navigator.share){$('nueva-pdf-msg').textContent='Este navegador no admite compartir PDF directamente. Descárgalo y adjúntalo en WhatsApp; en iPhone prueba Safari.';return;}
      await navigator.share({files:[f],title:'Cotización Nick Reyna DJ'});
      $('nueva-pdf-msg').textContent='Se abrió el menú para compartir.';
    }catch(e){if(e.name!=='AbortError')$('nueva-pdf-msg').textContent='No se pudo compartir ('+e.name+'). Usa Descargar PDF y adjúntalo en WhatsApp.';}
  });
})();
